<style>
html:has(#mapPanel:fullscreen),body:has(#mapPanel:fullscreen){margin:0!important;padding:0!important;overflow:hidden!important;background:#0f172a!important}
#mapPanel:fullscreen{box-sizing:border-box;width:100vw;height:100dvh;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;background:#0f172a!important;overflow:hidden!important}
#mapPanel:fullscreen #mapToolbar{display:none!important}
#mapPanel:fullscreen #mapFrameWrap{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;margin:0!important;padding:0!important;background:#0f172a!important;overflow:hidden!important}
#mapPanel:fullscreen #dynmapFrame{display:block!important;width:100%!important;height:100%!important;min-height:0!important;margin:0!important;padding:0!important;border:0!important;background:#0f172a!important}
