<script>(()=>{const panel=document.getElementById('mapPanel'),frame=document.getElementById('dynmapFrame'),button=document.getElementById('mapFullscreen'),fallback=document.getElementById('mapFallback');const sync=()=>button.textContent=document.fullscreenElement?'退出全屏':'全屏地图';button.addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await panel.requestFullscreen()}catch(e){fallback.classList.remove('hidden')}});document.addEventListener('fullscreenchange',sync);frame.addEventListener('error',()=>fallback.classList.remove('hidden'));sync()})();</script>
